member.example:
vytvoření:
	Pos2 posCs = new PosCs0203("COM1", baud9600);
			"terminál ČS 2.3 na portu COM1 s rychlostí 9600 Bd"
	nebo
	Pos2 posHypercom = GetPos(PosHypercom0205, "COM5", baud9600);
			"terminál Hypercom 2.5 na portu COM5 s rychlostí 9600 Bd"

použití:
	posCs.Purchase("AHSC017JRQ", 100.00);
			"spuštění operace platby s identifikací AHSC017JRQ na částku 100 (Kč)"
